python
def selectionProofFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    sums=set()
    def visit(i,s):
        if i==len(a):
            sums.add(s)
            return
        visit(i+1,s)
        visit(i+1,s+a[i])
    visit(0,0)
    out=sorted(sums)
    return next((x for x in out if x>=k),-1)


java
class Solution {
  public int selectionProofFirstQualifyingSlip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {Set<Integer>sums=new TreeSet<>();class Walk {void visit(int i,int s){if(i==a.length){sums.add(s);return;}visit(i+1,s);visit(i+1,s+a[i]);}}new Walk().visit(0,0);out.addAll(sums);}
    for(int x:out)if(x>=k)return x;return -1;
  }
}
